    let mut reversed = 0
    while num != 0 {
        let digit = num % 10
        reversed = reversed * 10 + digit
        num = num / 10
    }
    reversed
}
fn main() {
    let number = 1234
    let reversed_number = reverse_digits(number)
    print(reversed_number)
}

fn reverse_digits(n: Int) -> Int {
    let mut result = 0
    let mut num = n
    while num > 0 {
        result = result * 10 + (num % 10)
        num = num / 10
    }
    result
}
fn main() {
    print(reverse_digits(1234))
}

fn reverse_digits(n: Int) -> Int {
    let mut result = 0
    let mut remaining = n
    while remaining > 0 {
        let digit = remaining % 10
        result = result * 10 + digit
        remaining = remaining / 10
    }
    result
}
fn main() {
    let number = 1234
    print(reverse_digits(number))
}

